{"path": "islands/02-renorm/scratch/diag_solver.py", "content": """"Self-contained Python solver for f(q,r), for structural exploration only.
Implements MISSION section 2 recurrence. O(n^2) memory, fine for n <= ~3000.
Read-only w.r.t. GROUND_TRUTH; this is analysis code in our island's scratch.
"""
import sys

def build_f(n):
    """Return f as a 2D list f[q][r] for 0 <= r <= q <= n.
    f(q,r) = unique p with (p,q,r) P-position (f >= q), or stale carried value (< q).
    """
    # f is indexed [q][r], q from 0..n, r from 0..q
    f = [[0]*(q+1) for q in range(n+1)]
    for q in range(n+1):
        for r in range(q+1):
            if q == 0 and r == 0:
                f[0][0] = 1
            elif r > q:
                f[q][r] = f[q][q]
            elif f[q-1][r] < q:   # stale: carry
                f[q][r] = f[q-1][r]
            else:
                # mex over {f(a,r): a<q} U {f(q,b): b<r}
                s = set()
                for a in range(q):
                    s.add(f[a][r])
                for b in range(r):
                    s.add(f[q][b])
                m = 1
                while m in s:
                    m += 1
                f[q][r] = m
    return f

if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 100
    f = build_f(n)
    # diagonal f(q,q) = A029900(q)
    diag = [f[q][q] for q in range(n+1)]
    print("f(q,q) first 50:", diag[:50])"}

