    cnts = set()
    for i in range(len(w)-n+1):
        cnts.add(w[i:i+n].count('S'))
    return max(cnts)-min(cnts) <= 1
for n in [1,2,3,4,5,10,20,50,100]:
    print('n=%d balanced? %s' % (n, balanced(w)))
""}

